def mk(kind):
    def f(p,S,I):
        Vm,Km,Ki=p[0],p[1],p[2]
        if kind=='comp': return Vm*S/(Km*(1+I/Ki)+S)
        if kind=='uncomp': return Vm*S/(Km+S*(1+I/Ki))
        if kind=='noncomp': return Vm*S/((Km+S)*(1+I/Ki))
        if kind=='mixed':
            Ki2=p[3]; return Vm*S/(Km*(1+I/Ki)+S*(1+I/Ki2))
